const OHIO_TRIP="https://www.google.com/maps/dir/?api=1&travelmode=driving&destination="+GRAVES[3].ll.join(",")+"&waypoints="+encodeURIComponent([GRAVES[0],GRAVES[1],GRAVES[2]].map(g=>g.ll.join(",")).join("|"));
